"Darstellung":"Weergave",
"Darstellung (A)":"Weergave (A)",
"Darstellung (A): Material auf Körper ziehen":"Weergave (A): materiaal naar lichamen slepen",
"Darstellung auf einen Körper ziehen.":"Sleep een weergave naar een lichaam.",
"Darstellung der Körper":"Weergave van de lichamen",
"Darstellung wird aufbereitet …":"Weergave wordt voorbereid …",
"Darstellung zurückgesetzt (vom Material).":"Weergave hersteld (van materiaal).",
"Darstellung „{0}“ auf {1} Körper angewendet.":"Weergave “{0}” toegepast op {1} lichaam/lichamen.",
"Darstellungsqualität":"Weergavekwaliteit",
"Das Bild konnte nicht gelesen werden.":"De afbeelding kon niet worden gelezen.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"De afbeelding ligt als sjabloon op het vlak. Stel grootte, positie, rotatie en dekking daarna in het eigenschappenvenster in (bijv. breedte volgens een bekende afmeting).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Het resultaat van de geometriekernel is onleesbaar",
"Das Ergebnis konnte nicht geschrieben werden":"Het resultaat kon niet worden weggeschreven",
"Das Maß muss größer als 0 sein.":"De maat moet groter zijn dan 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"De mesh blijft een driehoeksmesh (geen B-Rep). Bewerken onder MESH: Repareren, Reduceren, Gladmaken, Vlaksnede … 3D-freesstrategieën in Fabricage kunnen de mesh direct bewerken.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Het profiel mag de as niet snijden. Een open lijn in de schets kan als as dienen.",
"Das Profil mit den jetzigen Werten überschreiben":"Het profiel overschrijven met de huidige waarden",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Het profiel wordt langs een lijn/polylijn geleid. Teken het profiel bij voorkeur loodrecht op het begin van het pad (bijv. profiel op XZ, pad op XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Het profiel wordt vanaf het schetsvlak verhoogd of verdiept gebosseld.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Het ruwe materiaal is de balk om het gekozen lichaam (plus verschuiving).",
"Das Setup hat keine Operationen.":"De opspanning heeft geen bewerkingen.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Het gereedschap freest in cirkels waarvan het middelpunt langs de gleuf verschuift. Het is nooit over de volle breedte in aanraking – dat staat grote stapdiepten toe en spaart frees en spil. De frees moet ongeveer 60 % van de gleufbreedte hebben.",
"Das Werkzeug schneidet die Fläche nicht":"Het gereedschap snijdt het oppervlak niet",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Het gereedschap snijdt in de richting van de gekozen vlakken tot het de opgegeven overmaten bereikt.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Het gereedschap duikt als een boor loodrecht in, rij voor rij, tot op het model plus overmaat. De snijkracht werkt langs de spil: geschikt voor lange gereedschappen, diepe holtes en weinig stijve machines. Het gereedschap moet over het midden snijden.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Het gereedschap vermijdt deze vlakken met inachtneming van de opgegeven veiligheidsafstanden (spanners, bankschroef).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Het gereedschap vermijdt deze vlakken terwijl het nabijgelegen vlakken bewerkt, en houdt de veiligheidsafstanden aan.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"De eerste Esc annuleert alleen het gereedschap of de selectie – een Esc te veel sluit de schets niet",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Dit is geen gat (afronding of pen) – klik op de binnenwand van een gat.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Dit is geen gat (cilindrisch vlak) – klik op de wand van het gat.",
"Das ist keine WerkFab-Design-Datei.":"Dit is geen WerkFab-themabestand.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Dit is geen schuine rand – klik op beide uiteinden van de afschuinrand.",
"Datei":"Bestand",
"Datei ist keine WerkFab-Einstellungsdatei.":"Het bestand is geen WerkFab-voorkeurenbestand.",
"Datei konnte nicht geöffnet werden:":"Bestand kon niet worden geopend:",
"Dateiendung":"Bestandsextensie",
