"Eigene Kopie „{0}“ angelegt{1} (auch in der Bibliothek) – der eingebaute Postprozessor bleibt unverändert":"Eigen kopie “{0}” aangemaakt{1} (ook in de bibliotheek) – de ingebouwde postprocessor blijft ongewijzigd",
"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Eigen sneltoetsen: open in de werkbalk het groepsmenu (▾), klik bij het commando op ⋮ → “Sneltoets wijzigen …”.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Eigen maten en opmerkingen kunnen op het blad met de muis worden versleept (afstand van de maatlijn, hoek van de verwijslijn, straal van de hoekboog). Twee hoeken aanklikken = lengtemaat. Een cirkelrand in het bovenaanzicht aanklikken = diameter (of straal). Hoek: eerst het hoekpunt, dan een hoekpunt op beide benen. Afschuining: beide uiteinden van de schuine rand – geeft bijv. 2×45°. In het tekstveld achter elke maat staat een toevoeging zoals ±0,1, H7 of 4×.",
