"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Een ronde frees laat in elke binnenhoek zijn radius staan – een hoekig tegenstuk past er dan niet in. De vrijsteek gaat bij elke scherpe binnenhoek kort de hoek in en terug.{0}{1}",
