"Erhebung":"Loft",
"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Loft heeft twee schetsen met gesloten profielen op verschillende vlakken nodig.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft heeft twee schetsen met elk één kromme nodig (op verschillende vlakken).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Loft niet mogelijk – controleer de doorsneden (elk één gesloten profiel, niet verdraaid)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"Loft niet mogelijk – één kromme per schets, dezelfde richting, niet verdraaid",
"Ersetzt den Standard-Kurzbefehl „{0}“.":"Vervangt de standaardsneltoets “{0}”.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Klik eerst op het vlak van het lichaam dat wordt verplaatst en daarna op het doelvlak van het andere lichaam. Het lichaam wordt gedraaid en verschoven tot het eerste klikpunt op het tweede ligt en de vlakken op elkaar liggen.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Klik eerst op de rand van het lichaam dat wordt verplaatst en daarna op de doelrand van het andere lichaam. Rechte randen vallen samen (midden op midden); bij cirkelranden – gat en pen – worden de assen gelijk gericht en de middelpunten samengebracht.",
