"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Vlakken aan het uiteinde van het onderdeel (tweevlak, vierkant, zeskant) met een aangedreven vingerfrees langs Z. Sleutelwijdte = tweemaal de afstand van het vlak tot de draaias. X en C bewegen samen (poolinterpolatie, Fanuc G12.1); zonder dit sjabloon in de postprocessor worden korte X/C-stapjes uitgevoerd.",
