"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Volgt alle scherpe buitenranden die van bovenaf bereikbaar zijn en breekt ze met de ontbraamdiepte – met de afschuinfrees als afschuining (gereedschapsas verticaal, punt buiten de rand), met de kogel-/lollipopfrees afgerond.",
