"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Contour met {0} punten – Okuma: G85 (LAP) met contour G81…G80, Fanuc: G71 P…Q…. De besturing voorfreest met haar eigen verdeling; de simulatie hier is de WerkFab-baan.",
