"Konturen außen und innen":"Buiten- en binnencontouren",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Contouren volgen de rand van de donkere vlakken. De hartlijn loopt door het midden van de lijnen – geschikt voor gravures en lijntekeningen. “Lijnen, bogen en cirkels” herkent rechte randen, scherpe hoeken, afrondingen en cirkels; “Polylijnen” volgt de afbeelding punt voor punt. Pas de schaal daarna zo nodig aan met “Sjabloon kalibreren” of “Schalen”.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Contouren met straalcorrectie in de besturing (RL/RR) worden met APPR/DEP genaderd en verlaten; de besturing berekent hulppunt en correctie zelf",
