"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Krommen van een schets op het voorvlak (dwars op de draaias) met een aangedreven frees langs Z (X en C bewegen samen; Fanuc: poolinterpolatie G12.1). Open krommen worden heen en terug gefreesd. Diepte vanaf het voorvlak.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Krommen van een schets die langs de draaias ligt, worden om de omtrek gewikkeld en gefreesd met een aangedreven frees die naar de as wijst (Z en C bewegen samen; Fanuc: cilinderinterpolatie G7.1). Het schetsvlak bepaalt de hoek waarop de contour zit; horizontale lijnstukken in de schets worden bogen om het onderdeel. Diepte vanaf de buitendiameter.",
"Kurzbefehl":"Sneltoets",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Korte wegen (tot de blijfafstand) legt het gereedschap beneden af met de overgangsvoeding in plaats van via de terugtrekhoogte – zonder botsingscontrole, houd dit dus klein.",
