"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Met steunpunten loopt de straal door de opgegeven waarden (positie in % van de randlengte). Dit wordt berekend door de volledige geometriekernel; de eerste keer duurt het laden enkele seconden.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Met de 3D-taster kan niet worden verspaand",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Vergelijken met het eindproduct: groen = op maat, blauw = restmateriaal, rood = te diep",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Met de muis naast een contour bewegen (de kant bepaalt de richting) · Esc beëindigt",
"Mit diesem Werkzeug kann nicht gefräst werden":"Met dit gereedschap kan niet worden gefreesd",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Met een tap alleen de cyclus “Tappen” gebruiken – een boorcyclus zou hem breken",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Met meerdere stappen wordt de draaddiepte in stappen gefreesd die elk ongeveer evenveel afnemen – spaart kleine draadfrezen en harde materialen. De lege gang volgt de laatste baan nog eens zonder stap.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Met „Boorcycli“ in het NC-programma worden besturingscycli uitgevoerd (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), anders uitgeschreven bewegingen.",
