"Nichts geändert: Die Nachbarflächen schließen diese Lücke nicht – zusammengehörige Flächen gemeinsam wählen (z. B. Wand und Boden einer Tasche)":"Niets gewijzigd: de aangrenzende vlakken sluiten deze opening niet – kies bij elkaar horende vlakken samen (bijv. wand en bodem van een tas)",
