"Noch kein Dreh-Setup: „Neues Setup“ → Bearbeitung „Drehen“ wählen.":"Nog geen draai-opspanning: „Nieuwe opspanning” → bewerking „Draaien” kiezen.",
"Noch kein Fräs-Setup vorhanden.":"Nog geen freesopspanning aanwezig.",
"Noch kein Körper gewählt – bis dahin gilt die relative Quadergröße.":"Nog geen lichaam gekozen – tot dan geldt de relatieve balkgrootte.",
"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"Nog geen lichaam aanwezig – modelleer eerst in CONSTRUCTIE.",
"Noch keine Designs gespeichert.":"Nog geen ontwerpen opgeslagen.",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"Nog geen opmerkingen. Leg met + notities bij het ontwerp vast.",
"Noch keine Operation":"Nog geen bewerking",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Nog geen sjablonen. Een sjabloon slaat strategieën op met alle instellingen (gereedschap, snijdata, hoogtes, passes, koppeling) om te hergebruiken in andere opspanningen en ontwerpen.",
"Noch keine Werkzeuge im Dokument.":"Nog geen gereedschappen in het document.",
