"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Alleen buitencontouren (tappen) werken als besturingscyclus",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Alleen diameter (vorm als dit gereedschap)",
"Nur Innenkonturen (Öffnungen)":"Alleen binnencontouren (openingen)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Alleen rechthoekige en ronde tassen werken als besturingscyclus",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Alleen bewerken wat een grotere frees in hoeken heeft laten staan.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Alleen de plaatsen van de contour nalopen die een grotere frees niet heeft bereikt (binnenhoeken, nauwe plekken). Zonder aanloop-/uitloopbogen, houdstegen en nafreesgangen; compensatie in de computer.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Alleen waar het referentiegereedschap er niet bij kon: vlakke gebieden parallel, steile gebieden als waterlijn. Bij een gereedschap uit de lijst telt de vorm ervan mee – bijvoorbeeld wat een torusfrees in de holle afrondingen laat staan.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Alleen platte vlakken kunnen als schetsvlak dienen.",
"Nur ebene Flächen können extrudiert werden":"Alleen vlakke vlakken kunnen worden geëxtrudeerd",
"Nur ebene Flächen lassen sich ersetzen":"Alleen vlakke vlakken kunnen worden vervangen",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Alleen vlakke vlakken en cilindervlakken (gaten, nokken) kunnen worden verschoven",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Alleen platte vlakken die naar boven naar het gereedschap wijzen (horizontaal in deze opspanning).",
