"Nut liegt nicht am Teil":"Gleuf ligt niet op het onderdeel",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Gleuf langs de draaias (bijv. spiebaan) met een aangedreven frees die naar de as wijst; de hoofdspil houdt het onderdeel als C-as vast. Gleufbreedte = frees-Ø. Start-/eind-Z in model-Z; reikt de gleuf tot het voorvlak, dan komt de frees van voren binnen, anders duikt hij bij de start in. Diepte vanaf de buitendiameter.",
