"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Open of gesloten krommen worden loodrecht op de schets getrokken – het resultaat is een oppervlak (wand zonder dikte). Met “Verdikken” of “Samenvoegen” wordt hier een volume van.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Open of gesloten krommen worden om de as gewenteld – het resultaat is een oppervlak, geen volume.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Zonder eigen toets geldt de standaard “{0}”.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Zonder “Gemodelleerd” wordt de schroefdraad alleen weergegeven (snel). Gemodelleerd wordt de draadvorm echt uitgesneden, bijv. voor 3D-printen. Gat voor M8 = Ø6,8.",
