"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: geen afvlakfunctie uitgevoerd (G5.1 is Fanuc) – stel Hi-Cut/Super-NURBS in op de machine in",
