"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Kamer in het voorvlak uit de gesloten contouren van een schets (binnencontouren blijven als eilanden staan), met een aangedreven vingerfrees langs Z. Er wordt van binnen naar buiten uitgeruimd; de frees duikt op een helling langs de binnenste baan in en blijft binnen een niveau beneden. X en C bewegen samen (Fanuc: poolinterpolatie G12.1). Diepte vanaf het voorvlak.",
