"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Wikkelt de schetskrommen op de cilinder: X blijft X, de afstand dwars op de as wordt een boog op de afwikkelings-Ø (rotatie A). De schets moet parallel aan de A-as liggen, bijv. op een raakvlak. Er wordt op vaste diepte onder het onderdeeloppervlak gefreesd – voor gravures, teksten en gleuven rond het onderdeel.",
