"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: Postprocessor zonder sjabloon “C-as en aangedreven gereedschap aan” – schakel C-as en gereedschapsspil handmatig in",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: Postprocessor zonder cilinderinterpolatie – Z en C bewegen samen; de voeding geldt dan, afhankelijk van de besturing, niet langs de baan. Vul beter het sjabloon „Cilinderinterpolatie aan/uit“ in",
